#!/usr/bin/env bash
# AKFC — Builder : infobulles lisibles et en français + palette de surlignage qui fonctionne.
#  Cause : les variables CSS de l'interface Tiptap (styles/_variables.scss) n'étaient chargées
#  NULLE PART → infobulles et fenêtre de surlignage sans fond ni couleurs (invisibles), et couleur
#  de surlignage indéfinie. Correctif :
#  - styles/tiptap-variables.css : uniquement les propriétés personnalisées de _variables.scss
#    (sans ses règles globales box-sizing / transition sur tous les éléments), chargé par le
#    layout racine → vaut aussi pour l'affichage public des surlignages.
#  - infobulles en français (Gras, Italique, Barré, Souligné, Titre, Liste…, Citation, Bloc de code,
#    Lien, Surligner, Aligner…, Annuler/Rétablir) ; palette : jaune, vert, bleu, rose, violet,
#    orange + « Retirer le surlignage ».
#  - infobulle native sur les contrôles icône-seule du builder (poignée de déplacement,
#    supprimer le bloc, retirer un élément de collection).
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-builder-tooltips-highlight.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
CSSF="apps/web/src/styles/tiptap-variables.css"
[ -f "$CSSF" ] && { echo "— déjà appliqué"; exit 0; }
U=apps/web/src/features/editor-tiptap/ui
FILES=($U/mark-button/use-mark.ts $U/heading-button/use-heading.ts $U/list-button/use-list.ts $U/text-align-button/use-text-align.ts $U/undo-redo-button/use-undo-redo.ts $U/blockquote-button/blockquote-button.tsx $U/blockquote-button/use-blockquote.ts $U/code-block-button/code-block-button.tsx $U/code-block-button/use-code-block.ts $U/link-popover/link-popover.tsx $U/link-popover/use-link-popover.ts $U/heading-dropdown-menu/heading-dropdown-menu.tsx $U/heading-dropdown-menu/use-heading-dropdown-menu.ts $U/list-dropdown-menu/list-dropdown-menu.tsx $U/list-dropdown-menu/use-list-dropdown-menu.ts $U/color-highlight-button/use-color-highlight.ts $U/color-highlight-popover/color-highlight-popover.tsx apps/web/src/app/layout.tsx apps/web/src/features/page-builder/components/BlockShell.tsx apps/web/src/features/page-builder/components/MediaListEditor.tsx)
BK=/tmp/akfc_tt_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do [ -f "$f" ] || { echo "ERREUR: $f introuvable." >&2; exit 1; }; mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$CSSF"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_tt; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"
echo "== application =="
echo '' | base64 -d > "$CSSF" && echo "  ok  $CSSF"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$CSSF" "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
fix(builder): infobulles en français et palette de surlignage (variables Tiptap chargées)

